// ---------- Potongan HTML bersama ----------
function timelineHtml(entries) {
  return (
    '<div class="timeline">' +
    entries
      .map(function (e) {
        return (
          "<article class=\"glass-panel\">" +
          '<div class="timeline-head"><h3>' + e.role + "</h3>" +
          '<p class="timeline-company">' + e.company + "</p>" +
          '<div class="timeline-chips">' +
          '<span class="chip chip-pill">' + ICONS.calendar + e.period + "</span>" +
          (e.location ? '<span class="chip chip-pill">' + ICONS.mapPin + e.location + "</span>" : "") +
          "</div></div>" +
          "<ul>" + e.highlights.map(function (h) { return "<li>" + h + "</li>"; }).join("") + "</ul>" +
          "</article>"
        );
      })
      .join("") +
    "</div>"
  );
}

function statsHtml() {
  return (
    '<section class="container stats">' +
    profile.stats
      .map(function (s) {
        return (
          '<div class="glass-panel stat-card">' +
          '<p class="stat-value">' + s.value + "</p>" +
          '<p class="stat-label">' + s.label + "</p>" +
          '<p class="stat-sub">' + s.sub + "</p>" +
          "</div>"
        );
      })
      .join("") +
    "</section>"
  );
}

function cardHtml() {
  return (
    '<div class="hanging-card-stage" id="card-stage">' +
    '<svg aria-hidden="true"><path id="lanyard-strap" class="hanging-card-rope" />' +
    '<text class="lanyard-text" dy="3.5"><textPath href="#lanyard-strap" startOffset="8">' +
    ("◉ " + profile.lanyardName + "   ").repeat(3) +
    "</textPath></text></svg>" +
    '<button type="button" class="hanging-card" id="hanging-card" data-dragging="false" ' +
    'aria-label="Kartu ' + profile.fullName + ', tarik untuk mengayunkan" title="Tarik untuk mengayunkan">' +
    '<span class="hanging-card-clip"></span>' +
    '<span class="hanging-card-hole"></span>' +
    '<span class="hanging-card-head">' +
    '<span class="hanging-card-title text-gradient">' + profile.cardTitle + "</span>" +
    '<span class="hanging-card-id">ID</span></span>' +
    '<span class="hanging-card-photo"><img src="' + PHOTO_SRC + '" alt="Foto ' + profile.fullName + '" width="283" height="283" draggable="false" /></span>' +
    '<span class="hanging-card-foot"><span style="text-align:left">' +
    '<span class="hanging-card-name">' + profile.fullName + "</span>" +
    '<span class="hanging-card-role">' + profile.cardSubtitle + "</span></span>" +
    '<span class="hanging-card-pull">Pull me</span></span>' +
    "</button></div>"
  );
}

