function projectCardHtml(p) {
  return (
    '<div class="glass-panel project-card"><div>' +
    '<p class="icon-inline">' + ICONS.code + p.category + "</p>" +
    "<h2>" + p.title + "</h2>" +
    '<p class="tiny muted" style="margin-top:0.5rem">' + p.role + " · " + p.period + "</p>" +
    '<p class="small muted leading" style="margin-top:1rem;max-width:36rem">' + p.desc + "</p>" +
    '<div class="chips">' + p.tech.map(function (t) { return '<span class="chip glass">' + t + "</span>"; }).join("") + "</div>" +
    '<div class="project-actions">' +
    '<a class="btn btn-outline" href="#/portofolio/' + p.slug + '">Detail Proyek ' + ICONS.arrowRight + "</a>" +
    (p.link ? '<a class="btn btn-ghost" href="' + p.link + '" target="_blank" rel="noreferrer">' + (p.linkLabel || "Buka Dashboard") + " ↗</a>" : "") +
    "</div></div>" +
    '<div class="project-metric">' + ICONS.users +
    (typeof p.visits === "number"
      ? '<p class="big">' + p.visits.toLocaleString("id-ID") + "+</p>" +
        '<p class="small" style="margin-top:0.5rem">' + p.metricLabel + "</p>"
      : '<p class="small muted" style="margin-top:1rem">Alat kerja harian untuk memantau proyek & task.</p>') +
    "</div></div>"
  );
}

