// ---------- Tema (gelap / terang) ----------
const THEME_KEY = "yussack-theme";
function readTheme() {
  try {
    return window.localStorage.getItem(THEME_KEY) === "light" ? "light" : "dark";
  } catch (e) {
    return "dark";
  }
}
function applyTheme(theme) {
  document.documentElement.classList.toggle("light", theme === "light");
}
function saveTheme(theme) {
  try {
    window.localStorage.setItem(THEME_KEY, theme);
  } catch (e) {
    /* penyimpanan diblokir — tema tetap berlaku untuk sesi ini */
  }
}
function toggleTheme() {
  const next = document.documentElement.classList.contains("light") ? "dark" : "light";
  applyTheme(next);
  saveTheme(next);
  updateThemeButton();
}
function updateThemeButton() {
  const btn = document.getElementById("theme-toggle");
  if (!btn) return;
  const dark = !document.documentElement.classList.contains("light");
  btn.setAttribute("aria-pressed", dark ? "true" : "false");
  btn.setAttribute("aria-label", dark ? "Mode gelap" : "Mode terang");
}
applyTheme(readTheme());

// ---------- Efek mengetik ----------
let typingTimer = null;
function startTyping() {
  const el = document.getElementById("typed");
  if (!el) return;
  const words = profile.typing;
  let i = 0, text = "", del = false;
  function tick() {
    const word = words[i % words.length];
    if (!del && text === word) {
      del = true;
      typingTimer = setTimeout(tick, 1400);
      return;
    }
    if (del && text === "") {
      del = false;
      i++;
      typingTimer = setTimeout(tick, 80);
      return;
    }
    text = del ? word.slice(0, text.length - 1) : word.slice(0, text.length + 1);
    el.textContent = text;
    typingTimer = setTimeout(tick, del ? 40 : 80);
  }
  tick();
}

// ---------- Fisika kartu lanyard (Matter.js) ----------
const CARD_WIDTH = 256;
const CARD_HEIGHT = 340;
const ROPE_LENGTH = 160;
const SEGMENTS = 8;
let cardCleanup = null;

function initHangingCard() {
  const frame = document.getElementById("card-stage");
  const cardEl = document.getElementById("hanging-card");
  const path = document.getElementById("lanyard-strap");
  if (!frame || !cardEl || !path || typeof Matter === "undefined") return;

  const { Bodies, Body, Composite, Constraint, Engine, Vector } = Matter;
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  let engine = null, anchor = null, rope = [], card = null, drag = null;
  let pointerId = null;
  let raf = 0;
  let disposed = false;

  function clampPoint(point) {
    return {
      x: Math.min(frame.clientWidth, Math.max(0, point.x)),
      y: Math.min(frame.clientHeight - 20, Math.max(anchor.y + 20, point.y)),
    };
  }

  function releaseDrag() {
    if (drag && engine) Composite.remove(engine.world, drag);
    drag = null;
  }

  function build() {
    if (frame.clientWidth < 260) return;
    if (engine) {
      releaseDrag();
      Composite.clear(engine.world, false);
      Engine.clear(engine);
    }
    engine = Engine.create({ positionIterations: 10, velocityIterations: 8, constraintIterations: 8 });
    anchor = { x: frame.clientWidth / 2, y: 12 };
    const group = Body.nextGroup(true);
    const segmentLength = ROPE_LENGTH / SEGMENTS;
    rope = [];
    for (let i = 0; i < SEGMENTS; i++) {
      const body = Bodies.circle(anchor.x, anchor.y + segmentLength * (i + 0.5), 4, {
        frictionAir: 0.06,
        collisionFilter: { group: group, mask: 0 },
      });
      Body.setMass(body, 0.08);
      rope.push(body);
    }
    card = Bodies.rectangle(anchor.x, anchor.y + ROPE_LENGTH + CARD_HEIGHT / 2, CARD_WIDTH, CARD_HEIGHT, {
      frictionAir: reducedMotion ? 0.12 : 0.018,
      restitution: 0.12,
      collisionFilter: { group: group },
    });
    Body.setMass(card, 6);
    const constraints = [];
    rope.forEach(function (body, i) {
      const previous = rope[i - 1];
      constraints.push(
        Constraint.create({
          bodyA: previous,
          pointA: previous ? { x: 0, y: 0 } : anchor,
          bodyB: body,
          length: previous ? segmentLength : segmentLength / 2,
          stiffness: 0.95,
          damping: 0.12,
        })
      );
    });
    const lastSegment = rope[rope.length - 1];
    constraints.push(
      Constraint.create({
        bodyA: lastSegment,
        bodyB: card,
        pointB: { x: 0, y: -CARD_HEIGHT / 2 },
        length: segmentLength / 2,
        stiffness: 0.95,
        damping: 0.12,
      })
    );
    const w = frame.clientWidth, h = frame.clientHeight;
    const walls = [
      Bodies.rectangle(-25, h / 2, 50, h * 3, { isStatic: true }),
      Bodies.rectangle(w + 25, h / 2, 50, h * 3, { isStatic: true }),
      Bodies.rectangle(w / 2, h + 25, w * 3, 50, { isStatic: true }),
    ];
    Composite.add(engine.world, rope.concat([card], constraints, walls));
    if (!reducedMotion) Body.setAngularVelocity(card, 0.015);
  }

  build();
  const resizeObserver = new ResizeObserver(function () { build(); });
  resizeObserver.observe(frame);

  let lastTime = 0, accumulator = 0;
  function animate(time) {
    if (disposed) return;
    if (engine && card) {
      accumulator += lastTime ? Math.min(time - lastTime, 50) : 1000 / 60;
      while (accumulator >= 1000 / 60) {
        Engine.update(engine, 1000 / 60);
        accumulator -= 1000 / 60;
      }
      cardEl.style.transform =
        "translate3d(" + (card.position.x - frame.clientWidth / 2) + "px, " +
        (card.position.y - CARD_HEIGHT / 2) + "px, 0) rotate(" + card.angle + "rad)";
      const attach = Vector.add(card.position, Vector.rotate({ x: 0, y: -CARD_HEIGHT / 2 }, card.angle));
      const points = [anchor].concat(rope.map(function (s) { return s.position; }), [attach]);
      let curve = "M " + points[0].x + " " + points[0].y;
      for (let i = 1; i < points.length - 1; i++) {
        const c = points[i], n = points[i + 1];
        curve += " Q " + c.x + " " + c.y + " " + (c.x + n.x) / 2 + " " + (c.y + n.y) / 2;
      }
      const end = points[points.length - 1];
      curve += " L " + end.x + " " + end.y;
      path.setAttribute("d", curve);
    }
    lastTime = time;
    raf = requestAnimationFrame(animate);
  }
  raf = requestAnimationFrame(animate);

  function localPoint(event) {
    const bounds = frame.getBoundingClientRect();
    return { x: event.clientX - bounds.left, y: event.clientY - bounds.top };
  }
  function grab(event) {
    if (event.button !== 0 || pointerId !== null || !engine) return;
    event.preventDefault();
    cardEl.focus({ preventScroll: true });
    cardEl.setPointerCapture(event.pointerId);
    pointerId = event.pointerId;
    cardEl.dataset.dragging = "true";
    const point = localPoint(event);
    releaseDrag();
    drag = Constraint.create({
      pointA: clampPoint(point),
      bodyB: card,
      pointB: Vector.sub(point, card.position),
      length: 0,
      stiffness: 0.16,
      damping: 0.12,
    });
    Composite.add(engine.world, drag);
  }
  function move(event) {
    if (pointerId !== event.pointerId || !drag) return;
    drag.pointA = clampPoint(localPoint(event));
  }
  function release(event) {
    if (pointerId !== event.pointerId) return;
    pointerId = null;
    cardEl.dataset.dragging = "false";
    releaseDrag();
    if (cardEl.hasPointerCapture(event.pointerId)) cardEl.releasePointerCapture(event.pointerId);
  }
  function nudge(direction) {
    if (!card) return;
    Body.setVelocity(card, { x: direction * 5, y: -1 });
    Body.setAngularVelocity(card, direction * 0.02);
  }
  function onKeyDown(event) {
    if (["ArrowLeft", "ArrowRight", "Enter", " "].indexOf(event.key) === -1) return;
    event.preventDefault();
    nudge(event.key === "ArrowLeft" ? -1 : 1);
  }
  function onClick(event) {
    if (event.detail === 0) nudge(1);
  }

  cardEl.addEventListener("pointerdown", grab);
  cardEl.addEventListener("pointermove", move);
  cardEl.addEventListener("pointerup", release);
  cardEl.addEventListener("pointercancel", release);
  cardEl.addEventListener("lostpointercapture", release);
  cardEl.addEventListener("keydown", onKeyDown);
  cardEl.addEventListener("click", onClick);

  cardCleanup = function () {
    disposed = true;
    cancelAnimationFrame(raf);
    resizeObserver.disconnect();
    releaseDrag();
    if (engine) {
      Composite.clear(engine.world, false);
      Engine.clear(engine);
    }
    engine = null;
  };
}

// ---------- Router hash ----------
const NAV_LINKS = [
  { hash: "#/", label: "Beranda" },
  { hash: "#/tentang", label: "Tentang" },
  { hash: "#/portofolio", label: "Portofolio" },
  { hash: "#/kontak", label: "Kontak" },
];

function currentHash() {
  return window.location.hash || "#/";
}

function renderNav() {
  const nav = document.getElementById("nav");
  const hash = currentHash();
  nav.innerHTML = NAV_LINKS.map(function (l) {
    const active = l.hash === "#/" ? hash === "#/" || hash === "" : hash.indexOf(l.hash) === 0;
    return '<a href="' + l.hash + '"' + (active ? ' class="active"' : "") + ">" + l.label + "</a>";
  }).join("") +
    '<button type="button" class="theme-toggle" id="theme-toggle" aria-label="Mode gelap" aria-pressed="true" title="Ganti tema">' +
    ICONS.moon +
    "</button>";
  document.getElementById("theme-toggle").addEventListener("click", toggleTheme);
  updateThemeButton();
}

const TITLES = {
  "#/": "Yussack Saputra — Project Management Officer",
  "#/tentang": "Tentang Saya — Yussack Saputra",
  "#/portofolio": "Portofolio & Perjalanan — Yussack Saputra",
  "#/kontak": "Kontak — Yussack Saputra",
};

function pageFor(hash) {
  if (hash === "#/" || hash === "") return { html: homePage(), title: TITLES["#/"], init: initHome };
  if (hash === "#/tentang") return { html: aboutPage(), title: TITLES["#/tentang"] };
  if (hash === "#/portofolio") return { html: portfolioPage(), title: TITLES["#/portofolio"], init: initPortfolio };
  if (hash.indexOf("#/portofolio/") === 0) {
    const slug = hash.slice("#/portofolio/".length);
    const detail = projectDetailPage(slug);
    const project = projects.find(function (x) { return x.slug === slug; });
    if (detail && project) return { html: detail, title: project.title + " — Yussack Saputra" };
  }
  if (hash === "#/kontak") return { html: contactPage(), title: TITLES["#/kontak"], init: initContact };
  return { html: homePage(), title: TITLES["#/"], init: initHome };
}

function initHome() {
  startTyping();
  initHangingCard();
}

function initPortfolio() {
  const panel = document.getElementById("tab-panel");
  const buttons = document.querySelectorAll('[role="tab"]');
  const initialPanel = panel.innerHTML;
  buttons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      buttons.forEach(function (b) {
        b.classList.toggle("btn-ghost", b !== btn);
        b.setAttribute("aria-selected", b === btn ? "true" : "false");
      });
      const content = portfolioTabHtml(btn.dataset.tab);
      panel.innerHTML = content === null ? initialPanel : content;
      panel.classList.remove("animate-rise");
      void panel.offsetWidth; // mulai ulang animasi
      panel.classList.add("animate-rise");
    });
  });
}

// ---------- Komentar (berjalan acak di bawah form) ----------
let comments = [];
function renderCommentMarquee() {
  const marquee = document.getElementById("comment-marquee");
  const track = document.getElementById("comment-track");
  if (!marquee || !track) return;
  if (comments.length === 0) {
    marquee.hidden = true;
    track.innerHTML = "";
    return;
  }
  marquee.hidden = false;
  const doubled = comments.concat(comments);
  track.innerHTML = doubled
    .map(function (x, i) {
      return (
        '<li class="glass comment-chip"' + (i >= comments.length ? ' aria-hidden="true"' : "") + ">" +
        '<span class="comment-avatar">' + x.name[0].toUpperCase() + "</span>" +
        '<span class="comment-chip-body"><span class="comment-chip-name">' + x.name + "</span>" +
        '<span class="comment-chip-text">' + x.text + "</span></span></li>"
      );
    })
    .join("");
  track.style.animationDuration = Math.max(16, comments.length * 6) + "s";
}

function initContact() {
  const form = document.getElementById("contact-form");
  form.addEventListener("submit", function (e) {
    e.preventDefault();
    const d = new FormData(form);
    const subject = encodeURIComponent("Pesan dari " + d.get("name"));
    const body = encodeURIComponent("Nama: " + d.get("name") + "\nEmail: " + d.get("email") + "\n\n" + d.get("msg"));
    window.location.href = "mailto:" + profile.email + "?subject=" + subject + "&body=" + body;
  });
  const commentForm = document.getElementById("comment-form");
  commentForm.addEventListener("submit", function (e) {
    e.preventDefault();
    const d = new FormData(commentForm);
    const name = String(d.get("cname")).trim();
    const text = String(d.get("ctext")).trim();
    if (!name || !text) return;
    // Acak urutan agar riwayat berjalan dalam urutan berbeda tiap kunjungan.
    comments = [{ name: name, text: text }].concat(comments).sort(function () { return Math.random() - 0.5; });
    renderCommentMarquee();
    commentForm.reset();
  });
}

function teardown() {
  if (typingTimer) {
    clearTimeout(typingTimer);
    typingTimer = null;
  }
  if (cardCleanup) {
    cardCleanup();
    cardCleanup = null;
  }
}

function render() {
  const app = document.getElementById("app");
  const page = pageFor(currentHash());
  comments = [];
  teardown();
  document.title = page.title;
  app.innerHTML = page.html;
  renderNav();
  window.scrollTo(0, 0);
  if (page.init) page.init();
}

let navigating = false;
window.addEventListener("hashchange", function () {
  if (navigating) return;
  navigating = true;
  const app = document.getElementById("app");
  app.classList.add("leaving");
  setTimeout(function () {
    app.classList.remove("leaving");
    render();
    navigating = false;
  }, 140);
});

document.getElementById("footer").innerHTML = footerHtml();
render();
